    if m.returncode != 0:
        print(f"#{pr} CONFLICT: {m.stdout.splitlines()[1:5]}")
        continue
    cur = git("commit-tree", m.stdout.splitlines()[0], "-p", cur, "-p", new[pr], "-m", "sim").stdout.strip()
