import json
import subprocess
import sys

T = "/Users/gabe/.claude/jobs/ba6a68d6/tmp"
old = json.load(open(f"{T}/old-heads.json"))
final = json.load(open(f"{T}/final-heads.json"))
BR = {"240": "docs/cleanup-stale-docs-adrs", "229": "feat/tagged-factory-components", "232": "feat/semantic-on-demand",
      "233": "feat/function-param-flags", "235": "fix/react-props-never-omitted", "241": "perf/component-lookups-by-name",
      "244": "fix/forwardref-by-shape"}
DRY = "--dry" in sys.argv


def git(*a):
    return subprocess.run(["/usr/bin/git", *a], capture_output=True, text=True)


git("fetch", "origin", "--quiet")
