for pr, b in BR.items():
    r = git("push", f"--force-with-lease={b}:{old[pr]}", "origin", f"{final[pr]}:refs/heads/{b}")
    print(f"#{pr} {b}: {old[pr][:8]} -> {final[pr][:8]}: {'pushed' if r.returncode == 0 else 'FAILED ' + r.stderr.strip()[:300]}")
    if r.returncode != 0:
        sys.exit(1)

